import CryptoJS from 'crypto-js'

/**
 * 生成 /auth/getToken 所需的身份校验密文（AES/CBC/PKCS7，密文标准 Base64）
 *
 * 明文格式：<13位毫秒时间戳>|<nonce(32位hex)>
 * 密钥来源：构建环境变量 VUE_APP_GET_TOKEN_AES_KEY / VUE_APP_GET_TOKEN_AES_IV（各 16 字节，
 *          必须与后端 Nacos auth.token-cipher.key / iv 完全一致）
 *
 * 依据：漏洞 VUL-20261104155309778683 整改，后端解密校验通过后才签发 token。
 * 注意：key/iv 必须 parse 成 WordArray，直接传字符串会被 CryptoJS 当作 passphrase 走
 * OpenSSL KDF + salt，导致后端用裸 key 解密失败。
 *
 * @returns {string} 标准 Base64 密文
 */
export function buildGetTokenCipher() {
  const rawKey = (process.env.VUE_APP_GET_TOKEN_AES_KEY || '').trim()
  const rawIv = (process.env.VUE_APP_GET_TOKEN_AES_IV || '').trim()
  if (!rawKey || !rawIv) {
    throw new Error('缺少 VUE_APP_GET_TOKEN_AES_KEY / VUE_APP_GET_TOKEN_AES_IV 构建变量')
  }

  const keyWA = CryptoJS.enc.Utf8.parse(rawKey)
  const ivWA = CryptoJS.enc.Utf8.parse(rawIv)
  if (keyWA.sigBytes !== 16 || ivWA.sigBytes !== 16) {
    throw new Error('VUE_APP_GET_TOKEN_AES_KEY / IV 必须为 16 字节')
  }

  // 16 字节随机 → 32 位 hex，每次请求重新生成（服务端 nonce 5 分钟内不可重复）
  const nonce = CryptoJS.lib.WordArray.random(16).toString()
  const plain = `${Date.now()}|${nonce}`

  const encrypted = CryptoJS.AES.encrypt(CryptoJS.enc.Utf8.parse(plain), keyWA, {
    iv: ivWA,
    mode: CryptoJS.mode.CBC,
    padding: CryptoJS.pad.Pkcs7
  })

  // 显式输出标准 Base64，不依赖默认 OpenSSL formatter（避免 Salted__ / 版本差异）
  return encrypted.ciphertext.toString(CryptoJS.enc.Base64)
}

